package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

public class OptionHasOptionalArgTest {

    @Test
    public void testDefaultOptionalArgIsFalse() throws Exception {
        Option opt = new Option("o", "description");
        // default should be false
        assertFalse(opt.hasOptionalArg(), "New Option should not have optional arg by default");

        // read private field optionalArg reflectively to confirm internal state
        Field optionalField = Option.class.getDeclaredField("optionalArg");
        optionalField.setAccessible(true);
        boolean internal = (boolean) optionalField.get(opt);
        assertFalse(internal, "Internal optionalArg field should be false by default");
    }

    @Test
    public void testSetOptionalArgTrue() throws Exception {
        Option opt = new Option("o", "description");

        // set via public setter
        opt.setOptionalArg(true);
        assertTrue(opt.hasOptionalArg(), "hasOptionalArg should return true after setOptionalArg(true)");

        // confirm private field updated as well
        Field optionalField = Option.class.getDeclaredField("optionalArg");
        optionalField.setAccessible(true);
        boolean internal = (boolean) optionalField.get(opt);
        assertTrue(internal, "Internal optionalArg field should be true after setOptionalArg(true)");
    }

    @Test
    public void testToggleOptionalArg() throws Exception {
        Option opt = new Option("o", "description");

        opt.setOptionalArg(true);
        assertTrue(opt.hasOptionalArg(), "should be true after setting to true");

        opt.setOptionalArg(false);
        assertFalse(opt.hasOptionalArg(), "should be false after setting to false");
    }

    @Test
    public void testModifyOptionalArgFieldReflectively() throws Exception {
        Option opt = new Option("o", "description");

        // directly change private field via reflection
        Field optionalField = Option.class.getDeclaredField("optionalArg");
        optionalField.setAccessible(true);
        optionalField.set(opt, true);

        // hasOptionalArg should reflect the change
        assertTrue(opt.hasOptionalArg(), "hasOptionalArg should reflect direct field modification to true");

        // set back to false reflectively
        optionalField.set(opt, false);
        assertFalse(opt.hasOptionalArg(), "hasOptionalArg should reflect direct field modification to false");
    }

    @Test
    public void testPrivateHasNoValuesReflectiveInteractionWithAddValue() throws Exception {
        Option opt = new Option("o", "description");

        // invoke private boolean hasNoValues() reflectively
        Method hasNoValues = Option.class.getDeclaredMethod("hasNoValues");
        hasNoValues.setAccessible(true);
        boolean emptyBefore = (boolean) hasNoValues.invoke(opt);
        assertTrue(emptyBefore, "A newly created Option should have no values");

        // add a value using the public (deprecated) API
        opt.addValue("val1");

        boolean emptyAfter = (boolean) hasNoValues.invoke(opt);
        assertFalse(emptyAfter, "Option should report having values after addValue");
    }
}

